-- Пополнение пула канала «Здоровый Взрослый»: 60 фраз (пачка владельца,
-- 2026-08). Канал публикует из пула в БД, а не из фолбэка, поэтому правка
-- src/bot/healthy-adult.data.ts без миграции до читателей не доезжает
-- (CLAUDE.md, раздел «Канал Здоровый Взрослый»; гейт check-pool-sync.mjs).
--
-- Тексты прошли планку healthy-adult.quality (род читателя, иишные штампы) —
-- ту же, через которую проходит пачка из админки.
--
-- Идемпотентно: каждая строка вставляется, только если такого текста в пуле
-- ещё нет (коррелированный NOT EXISTS по самой фразе, а не по первой из
-- пачки) — повторный прогон после отката дублей не наплодит.
-- "updatedAt" проставляется явно: колонка NOT NULL без DEFAULT (Prisma
-- @updatedAt ставит значение на клиенте) — инцидент 2026-07-16.

INSERT INTO "HealthyAdultPhrase" ("text", "sortOrder", "updatedAt")
SELECT seed."column1", seed."column2", CURRENT_TIMESTAMP FROM (VALUES
  ('Ты ждёшь результатов анализов с утра и каждые несколько минут проверяешь почту. Конечно, тебе тревожно. Ждать — это тоже труд, хотя руки при этом ничего не делают, и к обеду от него устают не меньше, чем от работы.', 100),
  ('Устать разрешено. Разрешения на это ни у кого спрашивать не нужно.', 101),
  ('Стоп. Я узнаю этот голос, и я знаю, откуда он взялся. Здесь так не говорят. Я стою между тобой и им, и я никуда не отойду.', 102),
  ('Прошло полгода, а рука всё ещё тянется набрать его номер. Так будет ещё какое-то время. Ты не делаешь ничего не так. Ты продолжаешь любить того, кого нет, и у этого нет неправильной скорости.', 103),
  ('Ты снова уходишь в сериал, четвёртая серия подряд, и я не ругаю. Этим ты спасаешься с тех пор, как дома было громко, и это работало. Сейчас дома тихо. Хочешь, посидим немного без экрана, а дальше как решишь?', 104),
  ('Я здесь. Не когда ты разберёшься и не когда станешь спокойнее — сейчас, пока всё вот так. Я никуда не тороплюсь и никуда не ухожу.', 105),
  ('«Из-за меня всё сорвалось» — это твои слова. А случилось вот что: температура под тридцать девять, и прийти не вышло. Болезнь — событие, а не поступок. Подводят поступками, а ты весь день лежишь под одеялом.', 106),
  ('Я понимаю, что тебе важно видеть меня на выходных. В эти выходные мне нужно побыть дома, и я не приеду. Причина не в тебе. Силы кончились, и мне нужна тишина.', 107),
  ('Ощущение, что жизнь прошла мимо, сейчас очень громкое. Оно говорит правду о том, как тебе больно, и не говорит правды о твоей жизни. Тебе тридцать четыре, многое ещё не решено. Это место, где выбирают, а не приговор. Спешить некуда.', 108),
  ('Про зарядку. Я тебя слышу: тело болит и не хочет. Предлагаю не зарядку, а пять шагов до окна и обратно, если захочется. Не захочется — ничего страшного, я не веду счёт.', 109),
  ('Слёзы из-за сломанной кружки — это слёзы о целом дне, в котором она оказалась последней. У людей так устроено: держишься, держишься, а потом какая-то мелочь открывает дверь всему остальному.', 110),
  ('Я слышу, что ты хочешь лучшего. И всё же: восемьдесят страниц за неделю — это то, что сделано. Почему не сто, мы сегодня обсуждать не будем. Сегодня мы это принимаем как есть.', 111),
  ('Злиться на маму — разрешено. Даже если она уже пожилая. Даже если она «хотела как лучше». Злость не отменяет любви, она стоит рядом с ней и просит, чтобы её тоже услышали.', 112),
  ('Купить себе цветы без повода — на это не нужно ничьего согласия. Тебе не обязательно сначала всё исправить, чтобы иметь право на красивое на столе.', 113),
  ('Я тебя вижу: ты стоишь у двери и ждёшь, когда они перестанут кричать. Я взрослый человек, и я здесь ради тебя. Больше на тебя кричать никто не будет, я не позволю. Дай мне руку.', 114),
  ('Тебе разрешается не отвечать на это сообщение сегодня. И завтра тоже, если сил не появится. Пауза никого не оскорбляет, а ты имеешь право отвечать тогда, когда сможешь.', 115),
  ('Ты злишься на брата, и злость здесь не ошибка. Он третий раз перенёс встречу, не спросив, удобно ли тебе. Под злостью — желание, чтобы с тобой считались. Желание правильное, а как сказать о нём брату, придумаем спокойно и вместе.', 116),
  ('Онемение после разговора с матерью — не равнодушие. Это то, что делает тело, когда бить нельзя и убежать нельзя. Оно тебя выручило, как умело, и я говорю ему спасибо.', 117),
  ('Тебя задело, как обошлись с новенькой, хотя тебя это никак не касалось. Вот это и есть то, во что ты веришь. Оно живёт в тебе даже тогда, когда тебе кажется, что ты ничего не отстаиваешь.', 118),
  ('Страшно звонить в клинику, я знаю. Если захочешь, я буду с тобой, пока ты набираешь, и мы только узнаем часы работы. Больше ничего сегодня не нужно. А если не сегодня — значит, не сегодня.', 119),
  ('Ты без сил, и я это вижу. Не «немного», а по-настоящему, до той точки, где даже выбрать, что поесть, уже слишком много. Эта усталость копилась не один день, и она имеет право быть такой большой.', 120),
  ('Критик зовёт этого человека ничтожеством из-за одной ошибки в отчёте. Я этого не приму — ни в такой форме, ни в такой громкости. Ошибку мы разберём, и разберём спокойно. А человека обсуждать в таком тоне я не дам.', 121),
  ('Никто не назначал тебе срок, к которому пора «уже отпустить». А если кто-то его назначил, это его нетерпение, а не твой срок. Я не тороплю. Пойдём со скоростью, с которой идётся.', 122),
  ('Спасибо тебе за умение шутить, когда больно. Этим умением ты много лет держишься за столом, где никто не спрашивает, как дела. Здесь спрашивают. Здесь можно и не шутить.', 123),
  ('Ночь, четвёртый час. Голова перебирает все промахи, какие смогла найти, потому что ей больше нечем заняться в темноте. Отвечать ей необязательно. Ладонь на грудь, если хочешь, и я с тобой до утра.', 124),
  ('Завидовать подруге, у которой всё сложилось, и одновременно радоваться за неё — так бывает, и одно не отменяет другого. Зависть здесь говорит о том, чего не хватает тебе, а не о том, как ты к ней относишься.', 125),
  ('Отдых, по-твоему, надо заслужить. Я с тобой в этом не соглашусь. Отдых полагается тому, у кого кончились силы, — а они кончились. На этом сегодня и остановимся.', 126),
  ('Не хотеть ехать на праздник к родителям — разрешённое чувство. Ты можешь поехать и не хотеть, а можешь не поехать. Любить их и не хотеть ехать — вещи совместимые, я это точно знаю.', 127),
  ('Тебе кажется, что все заметили, как у тебя дрожал голос. А было так: люди смотрели в свои телефоны и думали про обед. Эту дрожь слышишь только ты, и она уже позади.', 128),
  ('Мне жаль, что тебе обидно, я это слышу. И всё же денег в этот раз я не дам. Это моё решение, и я по-прежнему на твоей стороне.', 129),
  ('Не хочется — понимаю, и заставлять не стану. Если появится немного сил, можно только открыть файл и посмотреть, не начиная. Если не появится, значит, не сегодня, и это тоже ответ.', 130),
  ('«Я слишком много чувствую» — так ты это называешь. У меня для этого другое имя: тебя долго учили чувствовать поменьше, а выучиться не вышло. Никакой поломки здесь нет. Есть чувствительность, которая не согласилась исчезнуть, и хорошо, что не согласилась.', 131),
  ('Я хочу, чтобы у тебя было не только «справиться», но и «пожить». Мороженое на набережной, сон до десяти, долгий разговор ни о чём, книга не по работе. Заслуживать это не нужно. Ради этого ты вообще держишься.', 132),
  ('Обидно, когда про её день рождения помнишь только ты, а про твой забывают. Обида здесь на своём месте, ей не нужно ничего доказывать. На твоём месте мне было бы обидно тоже.', 133),
  ('Ты говоришь «ничтожество». Я смотрю на того же человека и вижу: третий год тянет двоих, а сегодня сил не осталось. Твоё слово к нему не подходит, и дальше меня оно не пройдёт.', 134),
  ('Плакать по собаке сильнее, чем по дедушке, — можно, и стыдиться тут нечего. Горе не сверяется с тем, кто «важнее». Оно идёт туда, где было больше ежедневного тепла.', 135),
  ('Я знаю, что ты перепроверяешь письмо восьмой раз: так когда-то удавалось спастись от крика. И это работало. Сейчас кричать некому, и письмо давно готово. Я останусь с тобой, если ты решишь его отправить, и если не решишь — тоже.', 136),
  ('Говори что угодно, я останусь. Можешь злиться на меня, можешь молчать час. Я буду рядом всё это время, и меняться ради этого не нужно.', 137),
  ('Никакой справки, чтобы принять помощь, не требуется. Ни диагноза, ни срыва, ни доказательств, что до этого были честные попытки справиться в одиночку, ни чужого разрешения. Тебе тяжело — этого хватает.', 138),
  ('Я вижу, как у тебя сжимается челюсть, когда он говорит «ну ты же понимаешь». Это тело сообщает, что с тобой так нельзя, и оно не ошибается. Гнев здесь — та самая черта, дальше которой с тобой нельзя; он проснулся раньше, чем нашлись слова.', 139),
  ('Лень тут ни при чём. У тебя с утра во рту ни крошки.', 140),
  ('Повышение прошло мимо, потому что кто-то должен забирать сына из сада, и это ты. Кто-то назовёт такое шагом назад. А я смотрю на человека, который знает, зачем живёт, и делает это каждый день в пять часов вечера.', 141),
  ('Одно письмо. Не ответ на все восемнадцать, а одно, самое короткое, и то если захочется. Если получится — хорошо. Если нет, я всё равно здесь, и завтра тоже.', 142),
  ('Хотеть, чтобы тебя пожалели, — обычное человеческое желание, не детское и не стыдное. Взрослые тоже в этом нуждаются, просто редко говорят вслух. Мне можно сказать.', 143),
  ('Хорошо, что ты держишь планку. А передо мной человек, который держит её уже без сна. Сегодня планка опускается до «сделать и лечь». Это моё решение, и я его не отменю.', 144),
  ('«Избалованность» — так ты это зовёшь, потому что не можешь есть остывшую еду, которую поставили перед тобой без единого слова. Вблизи дело не в еде. Дело в том, что тебе снова дали, не спросив, и снова ждут благодарности.', 145),
  ('Мне ценно, что ты делишься со мной. И сейчас я не могу слушать про его измены третий вечер подряд: у меня внутри не осталось места. Позвони завтра, я хочу тебя услышать.', 146),
  ('Голова уже дописала: он не ответил, значит, всё кончено. А на самом деле есть вот что: четыре часа молчания, в рабочий день, во вторник. Это молчание пока ничего не значит. Я побуду с тобой, пока оно длится.', 147),
  ('Давай попробуем вместе: не всю посуду, а одну чашку, и остановиться, если станет тяжело. Я буду рядом, и разрешение остановиться настоящее, а не для вида.', 148),
  ('Тебе не нужно быть в порядке к понедельнику. Такого срока никто не назначал. Приходить в себя после ссоры или после плохой недели — это идёт столько, сколько идёт, и я не буду тебя торопить.', 149),
  ('Нет. Ты не будешь называть это позором и пересказывать по кругу перед сном. Я слышу каждое слово, и я говорю тебе спокойно: на сегодня закончили.', 150),
  ('Ты сердишься на неё за то, что она ушла, и тут же стыдишься этого. Я вижу оба чувства, и обоим есть место. Они оба горюют, просто у злости голос громче.', 151),
  ('Ты заедаешь тревогу по ночам, и ругать тебя за это я не стану. Еда была единственным тёплым, что приходило вовремя. Я хочу приходить так же вовремя, чтобы у тебя появился выбор.', 152),
  ('Тебе больно оттого, как она это сказала. При всех, и ответить было нечего, а потом всю дорогу домой в голове складывались правильные слова. Я слышу. Такое не отпускает за один вечер, так бывает с любым, кого задели при людях.', 153),
  ('Уйти с вечеринки в десять, потому что кончились силы, — твоё право, и объяснять его никому не нужно. Усталость — сама по себе причина, и другой не требуется.', 154),
  ('Ты сравниваешь себя с Лёшей, который в тридцать уже руководит отделом. Я не буду это сравнение поддерживать. У Лёши своя дорога и своя цена за неё, о которой ты ничего не знаешь. Здесь ни с кем не соревнуются.', 155),
  ('Да, был срыв и был крик. Это случилось, и с этим можно что-то сделать: подойти, назвать, что было, извиниться. Один вечер не отменяет восьми лет, в которых ты для неё опора. Оба факта правдивы, и я держу оба.', 156),
  ('Когда ты повышаешь голос, я перестаю слышать, что ты говоришь. А я хочу тебя услышать. Поэтому я выйду ненадолго и вернусь, когда получится говорить тише.', 157),
  ('Чтобы начать, не нужно начинать всё с нуля. Если появится желание, первым шагом может быть тетрадь, брошенная в марте: найти её и положить на стол. Пока только это, и я не подгоняю.', 158),
  ('Ты спрашиваешь, зачем всё это, если конца не видно. Отвечать за тебя я не буду. Скажу одно: в основе твоего выбора было желание, чтобы люди уходили из твоего кабинета легче, чем входили. Оно никуда не делось, оно просто устало вместе с тобой.', 159)
) AS seed
WHERE NOT EXISTS (
  SELECT 1 FROM "HealthyAdultPhrase" p WHERE p."text" = seed."column1"
);
